mapper.select:
SELECT * FROM (
    SELECT ROWNUM AS rnum, A.* FROM (
        SELECT r.report_sid as reportSid, d.diary_title as diaryTitle, d.reg_id as regId
        FROM report r JOIN diary d ON r.diary_sid = d.diary_sid
        ORDER BY r.report_sid DESC
    ) A WHERE ROWNUM <= #{pageNo} * #{pageSize}
) WHERE rnum > (#{pageNo} - 1) * #{pageSize}

SELECT * FROM (
    SELECT ROWNUM AS rnum, A.* FROM (
        SELECT user_id as userId, nickname, admin_chk as adminChk
        FROM users WHERE 1=1

            AND user_id LIKE '%' || #{searchWord} || '%'

        ORDER BY user_id ASC
    ) A WHERE ROWNUM <= #{pageNo} * #{pageSize}
) WHERE rnum > (#{pageNo} - 1) * #{pageSize}

SELECT * FROM (
    SELECT ROWNUM AS rnum, A.* FROM (
        SELECT diary_sid as diarySid, reg_id as regId, diary_title as diaryTitle, diary_status as diaryStatus
        FROM diary ORDER BY diary_sid DESC
    ) A WHERE ROWNUM <= #{pageNo} * #{pageSize}
) WHERE rnum > (#{pageNo} - 1) * #{pageSize}
